use std::hash::Hash;

use derive_more::Debug;
use named_id::RenameAll;

/// The complete set of actions that be performed on a protocol model.
///
/// The two generic types are for Action and Data,
/// and their use is a bit complex but important to understand:
///
/// Protocol models use their own protocol-specific Action and Data types.
/// The rest of the system, from RoutingDispatchModel to NodeModel to NetworkModel,
/// use enum types representing all possible Action/Data types for all known protocols.
/// These enums are generated by the `[simdash_routing_dispatch::routing_protocols!]` macro.
#[derive(Debug, Clone, PartialEq, Eq, RenameAll)]
pub enum RoutingAction<A, D: Eq + Hash> {
    /// A protocol-specific action, defined by the protocol model
    Protocol(A),
    /// An action triggered by network behavior,
    /// always due to a [`crate::ProtocolFx::Network`] effect.
    Network(ProtocolNetworkAction<D>),
}

impl<A, D: Eq + Hash> From<A> for RoutingAction<A, D> {
    fn from(action: A) -> Self {
        RoutingAction::Protocol(action)
    }
}

impl<A, D: Eq + Hash> RoutingAction<A, D> {
    /// Convenience method to create a Receive action.
    pub fn receive(data: D) -> Self {
        RoutingAction::Network(ProtocolNetworkAction::Receive { data })
    }

    /// Convenience method to create a Tick action.
    pub fn tick() -> Self {
        RoutingAction::Network(ProtocolNetworkAction::Tick)
    }

    /// Convenience method to wrap a Protocol action.
    pub fn protocol(action: A) -> Self {
        RoutingAction::Protocol(action)
    }
}

/// An action triggered by network behavior,
/// always due to a [`crate::ProtocolFx::Network`] effect.
#[derive(Debug, Clone, PartialEq, Eq, RenameAll)]
pub enum ProtocolNetworkAction<D: Eq + Hash> {
    /// An action to receive data from the network
    #[debug("Receive({:?})", data)]
    Receive {
        /// The protocol wire data received
        data: D,
    },
    /// An action to advance the protocol state by one tick
    Tick,
}
